253|size_t ZSTD_CCtx_setParameter(ZSTD_CCtx* cctx, ZSTD_cParameter param, unsigned value)
254|{
255|    if (cctx->streamStage != zcss_init) return ERROR(stage_wrong);
256|
257|    switch(param)
258|    {
259|    case ZSTD_p_compressionLevel:
260|        if (value == 0) return 0;  /* special value : 0 means "don't change anything" */
261|        if (cctx->cdict) return ERROR(stage_wrong);
262|        return ZSTD_CCtxParam_setParameter(&cctx->requestedParams, param, value);
263|
264|    case ZSTD_p_windowLog:
265|    case ZSTD_p_hashLog:
266|    case ZSTD_p_chainLog:
267|    case ZSTD_p_searchLog:
268|    case ZSTD_p_minMatch:
269|    case ZSTD_p_targetLength:
270|    case ZSTD_p_compressionStrategy:
271|        if (value == 0) return 0;  /* special value : 0 means "don't change anything" */
272|        if (cctx->cdict) return ERROR(stage_wrong);
273|        ZSTD_cLevelToCParams(cctx);  /* Can optimize if srcSize is known */
274|        return ZSTD_CCtxParam_setParameter(&cctx->requestedParams, param, value);
275|
276|    case ZSTD_p_contentSizeFlag:
277|    case ZSTD_p_checksumFlag:
278|    case ZSTD_p_dictIDFlag:
279|        return ZSTD_CCtxParam_setParameter(&cctx->requestedParams, param, value);
280|
281|    case ZSTD_p_forceMaxWindow :  /* Force back-references to remain < windowSize,
282|                                   * even when referencing into Dictionary content
283|                                   * default : 0 when using a CDict, 1 when using a Prefix */
284|        cctx->loadedDictEnd = 0;
285|        return ZSTD_CCtxParam_setParameter(&cctx->requestedParams, param, value);
286|
287|    case ZSTD_p_nbThreads:
288|        if (value==0) return 0;
289|        DEBUGLOG(5, " setting nbThreads : %u", value);
290|        if (value > 1 && cctx->staticSize) {
291|            return ERROR(parameter_unsupported);  /* MT not compatible with static alloc */
292|        }
293|        return ZSTD_CCtxParam_setParameter(&cctx->requestedParams, param, value);
294|
295|    case ZSTD_p_jobSize:
296|        return ZSTD_CCtxParam_setParameter(&cctx->requestedParams, param, value);
297|
298|    case ZSTD_p_overlapSizeLog:
299|        DEBUGLOG(5, " setting overlap with nbThreads == %u", cctx->requestedParams.nbThreads);
300|        return ZSTD_CCtxParam_setParameter(&cctx->requestedParams, param, value);
301|
302|    case ZSTD_p_enableLongDistanceMatching:
303|        if (cctx->cdict) return ERROR(stage_wrong);
304|        if (value != 0) {
305|            ZSTD_cLevelToCParams(cctx);
306|        }
307|        return ZSTD_CCtxParam_setParameter(&cctx->requestedParams, param, value);
308|
309|    case ZSTD_p_ldmHashLog:
310|    case ZSTD_p_ldmMinMatch:
311|        if (value == 0) return 0;  /* special value : 0 means "don't change anything" */
312|        if (cctx->cdict) return ERROR(stage_wrong);
313|        return ZSTD_CCtxParam_setParameter(&cctx->requestedParams, param, value);
314|
315|    case ZSTD_p_ldmBucketSizeLog:
316|    case ZSTD_p_ldmHashEveryLog:
317|        if (cctx->cdict) return ERROR(stage_wrong);
318|        return ZSTD_CCtxParam_setParameter(&cctx->requestedParams, param, value);
319|
320|    default: return ERROR(parameter_unsupported);
321|    }
