638|ZSTD_compressionParameters ZSTD_adjustCParams_internal(ZSTD_compressionParameters cPar, unsigned long long srcSize, size_t dictSize)
639|{
640|    assert(ZSTD_checkCParams(cPar)==0);
641|    if (srcSize+dictSize == 0) return cPar;   /* no size information available : no adjustment */
642|
643|    /* resize params, to use less memory when necessary */
644|    {   U32 const minSrcSize = (srcSize==0) ? 500 : 0;
645|        U64 const rSize = srcSize + dictSize + minSrcSize;
646|        if (rSize < ((U64)1<<ZSTD_WINDOWLOG_MAX)) {
647|            U32 const srcLog =
648|                    MAX(ZSTD_HASHLOG_MIN, (rSize==1) ? 1 : ZSTD_highbit32((U32)(rSize)-1) + 1);
649|            if (cPar.windowLog > srcLog) cPar.windowLog = srcLog;
650|    }   }
651|    if (cPar.hashLog > cPar.windowLog) cPar.hashLog = cPar.windowLog;
652|    {   U32 const cycleLog = ZSTD_cycleLog(cPar.chainLog, cPar.strategy);
653|        if (cycleLog > cPar.windowLog) cPar.chainLog -= (cycleLog - cPar.windowLog);
654|    }
655|
656|    if (cPar.windowLog < ZSTD_WINDOWLOG_ABSOLUTEMIN) cPar.windowLog = ZSTD_WINDOWLOG_ABSOLUTEMIN;  /* required for frame header */
657|
658|    return cPar;
659|}

