667|size_t ZSTD_estimateCCtxSize_advanced_usingCCtxParams(const ZSTD_CCtx_params* params)
668|{
669|    /* Estimate CCtx size is supported for single-threaded compression only. */
670|    if (params->nbThreads > 1) { return ERROR(GENERIC); }
671|    {   ZSTD_compressionParameters const cParams =
672|                ZSTD_getCParamsFromCCtxParams(*params, 0, 0);
673|        size_t const blockSize = MIN(ZSTD_BLOCKSIZE_MAX, (size_t)1 << cParams.windowLog);
674|        U32    const divider = (cParams.searchLength==3) ? 3 : 4;
675|        size_t const maxNbSeq = blockSize / divider;
676|        size_t const tokenSpace = blockSize + 11*maxNbSeq;
677|        size_t const chainSize =
678|                (cParams.strategy == ZSTD_fast) ? 0 : ((size_t)1 << cParams.chainLog);
679|        size_t const hSize = ((size_t)1) << cParams.hashLog;
680|        U32    const hashLog3 = (cParams.searchLength>3) ?
681|                                0 : MIN(ZSTD_HASHLOG3_MAX, cParams.windowLog);
682|        size_t const h3Size = ((size_t)1) << hashLog3;
683|        size_t const entropySpace = sizeof(ZSTD_entropyCTables_t);
684|        size_t const tableSpace = (chainSize + hSize + h3Size) * sizeof(U32);
685|
686|        size_t const optBudget =
687|                ((MaxML+1) + (MaxLL+1) + (MaxOff+1) + (1<<Litbits))*sizeof(U32)
688|                + (ZSTD_OPT_NUM+1)*(sizeof(ZSTD_match_t) + sizeof(ZSTD_optimal_t));
689|        size_t const optSpace = ((cParams.strategy == ZSTD_btopt) || (cParams.strategy == ZSTD_btultra)) ? optBudget : 0;
690|
691|        size_t const ldmSpace = params->ldmParams.enableLdm ?
692|            ZSTD_ldm_getTableSize(params->ldmParams.hashLog,
693|                                  params->ldmParams.bucketSizeLog) : 0;
694|
695|        size_t const neededSpace = entropySpace + tableSpace + tokenSpace +
696|                                   optSpace + ldmSpace;
697|
698|        DEBUGLOG(5, "sizeof(ZSTD_CCtx) : %u", (U32)sizeof(ZSTD_CCtx));
699|        DEBUGLOG(5, "estimate workSpace : %u", (U32)neededSpace);
700|        return sizeof(ZSTD_CCtx) + neededSpace;
701|    }
702|}

