740|static U32 ZSTD_equivalentCParams(ZSTD_compressionParameters cParams1,
741|                                  ZSTD_compressionParameters cParams2)
742|{
743|    U32 bslog1 = MIN(cParams1.windowLog, ZSTD_BLOCKSIZELOG_MAX);
744|    U32 bslog2 = MIN(cParams2.windowLog, ZSTD_BLOCKSIZELOG_MAX);
745|    return (bslog1 == bslog2)   /* same block size */
746|         & (cParams1.hashLog  == cParams2.hashLog)
747|         & (cParams1.chainLog == cParams2.chainLog)
748|         & (cParams1.strategy == cParams2.strategy)   /* opt parser space */
749|         & ((cParams1.searchLength==3) == (cParams2.searchLength==3));  /* hashlog3 space */
750|}

