1592|static size_t ZSTD_compress_frameChunk (ZSTD_CCtx* cctx,
1593|                                     void* dst, size_t dstCapacity,
1594|                               const void* src, size_t srcSize,
1595|                                     U32 lastFrameChunk)
1596|{
1597|    size_t blockSize = cctx->blockSize;
1598|    size_t remaining = srcSize;
1599|    const BYTE* ip = (const BYTE*)src;
1600|    BYTE* const ostart = (BYTE*)dst;
1601|    BYTE* op = ostart;
1602|    U32 const maxDist = (U32)1 << cctx->appliedParams.cParams.windowLog;
1603|
1604|    if (cctx->appliedParams.fParams.checksumFlag && srcSize)
1605|        XXH64_update(&cctx->xxhState, src, srcSize);
1606|
1607|    while (remaining) {
1608|        U32 const lastBlock = lastFrameChunk & (blockSize >= remaining);
1609|        size_t cSize;
1610|
1611|        if (dstCapacity < ZSTD_blockHeaderSize + MIN_CBLOCK_SIZE)
1612|            return ERROR(dstSize_tooSmall);   /* not enough space to store compressed block */
1613|        if (remaining < blockSize) blockSize = remaining;
1614|
1615|        /* preemptive overflow correction:
1616|         * 1. correction is large enough:
1617|         *    lowLimit > (3<<29) ==> current > 3<<29 + 1<<windowLog - blockSize
1618|         *    1<<windowLog <= newCurrent < 1<<chainLog + 1<<windowLog
1619|         *
1620|         *    current - newCurrent
1621|         *    > (3<<29 + 1<<windowLog - blockSize) - (1<<windowLog + 1<<chainLog)
1622|         *    > (3<<29 - blockSize) - (1<<chainLog)
1623|         *    > (3<<29 - blockSize) - (1<<30)             (NOTE: chainLog <= 30)
1624|         *    > 1<<29 - 1<<17
1625|         *
1626|         * 2. (ip+blockSize - cctx->base) doesn't overflow:
1627|         *    In 32 bit mode we limit windowLog to 30 so we don't get
1628|         *    differences larger than 1<<31-1.
1629|         * 3. cctx->lowLimit < 1<<32:
1630|         *    windowLog <= 31 ==> 3<<29 + 1<<windowLog < 7<<29 < 1<<32.
1631|         */
1632|        if (cctx->lowLimit > (3U<<29)) {
1633|            U32 const cycleMask = ((U32)1 << ZSTD_cycleLog(cctx->appliedParams.cParams.chainLog, cctx->appliedParams.cParams.strategy)) - 1;
1634|            U32 const current = (U32)(ip - cctx->base);
1635|            U32 const newCurrent = (current & cycleMask) + ((U32)1 << cctx->appliedParams.cParams.windowLog);
1636|            U32 const correction = current - newCurrent;
1637|            ZSTD_STATIC_ASSERT(ZSTD_CHAINLOG_MAX <= 30);
1638|            ZSTD_STATIC_ASSERT(ZSTD_WINDOWLOG_MAX_32 <= 30);
1639|            ZSTD_STATIC_ASSERT(ZSTD_WINDOWLOG_MAX <= 31);
1640|            assert(current > newCurrent);
1641|            assert(correction > 1<<28); /* Loose bound, should be about 1<<29 */
1642|            ZSTD_reduceIndex(cctx, correction);
1643|            cctx->base += correction;
1644|            cctx->dictBase += correction;
1645|            cctx->lowLimit -= correction;
1646|            cctx->dictLimit -= correction;
1647|            if (cctx->nextToUpdate < correction) cctx->nextToUpdate = 0;
1648|            else cctx->nextToUpdate -= correction;
1649|            DEBUGLOG(4, "Correction of 0x%x bytes to lowLimit=0x%x\n", correction, cctx->lowLimit);
1650|        }
1651|
1652|        if ((U32)(ip+blockSize - cctx->base) > cctx->loadedDictEnd + maxDist) {
1653|            /* enforce maxDist */
1654|            U32 const newLowLimit = (U32)(ip+blockSize - cctx->base) - maxDist;
1655|            if (cctx->lowLimit < newLowLimit) cctx->lowLimit = newLowLimit;
1656|            if (cctx->dictLimit < cctx->lowLimit) cctx->dictLimit = cctx->lowLimit;
1657|        }
1658|
1659|        cSize = ZSTD_compressBlock_internal(cctx, op+ZSTD_blockHeaderSize, dstCapacity-ZSTD_blockHeaderSize, ip, blockSize);
1660|        if (ZSTD_isError(cSize)) return cSize;
