288|size_t ZSTD_getFrameHeader(ZSTD_frameHeader* zfhPtr, const void* src, size_t srcSize)
289|{
290|    const BYTE* ip = (const BYTE*)src;
291|    if (srcSize < ZSTD_frameHeaderSize_prefix) return ZSTD_frameHeaderSize_prefix;
292|
293|    if (MEM_readLE32(src) != ZSTD_MAGICNUMBER) {
294|        if ((MEM_readLE32(src) & 0xFFFFFFF0U) == ZSTD_MAGIC_SKIPPABLE_START) {
295|            /* skippable frame */
296|            if (srcSize < ZSTD_skippableHeaderSize)
297|                return ZSTD_skippableHeaderSize; /* magic number + frame length */
298|            memset(zfhPtr, 0, sizeof(*zfhPtr));
299|            zfhPtr->frameContentSize = MEM_readLE32((const char *)src + 4);
300|            zfhPtr->frameType = ZSTD_skippableFrame;
301|            return 0;
302|        }
303|        return ERROR(prefix_unknown);
304|    }
305|
306|    /* ensure there is enough `srcSize` to fully read/decode frame header */
307|    {   size_t const fhsize = ZSTD_frameHeaderSize(src, srcSize);
308|        if (srcSize < fhsize) return fhsize;
309|        zfhPtr->headerSize = (U32)fhsize;
310|    }
311|
312|    {   BYTE const fhdByte = ip[4];
313|        size_t pos = 5;
314|        U32 const dictIDSizeCode = fhdByte&3;
315|        U32 const checksumFlag = (fhdByte>>2)&1;
316|        U32 const singleSegment = (fhdByte>>5)&1;
317|        U32 const fcsID = fhdByte>>6;
318|        U64 windowSize = 0;
319|        U32 dictID = 0;
320|        U64 frameContentSize = ZSTD_CONTENTSIZE_UNKNOWN;
321|        if ((fhdByte & 0x08) != 0)
322|            return ERROR(frameParameter_unsupported); /* reserved bits, must be zero */
323|
324|        if (!singleSegment) {
325|            BYTE const wlByte = ip[pos++];
326|            U32 const windowLog = (wlByte >> 3) + ZSTD_WINDOWLOG_ABSOLUTEMIN;
327|            if (windowLog > ZSTD_WINDOWLOG_MAX)
328|                return ERROR(frameParameter_windowTooLarge);
329|            windowSize = (1ULL << windowLog);
330|            windowSize += (windowSize >> 3) * (wlByte&7);
331|        }
332|        switch(dictIDSizeCode)
333|        {
334|            default: assert(0);  /* impossible */
335|            case 0 : break;
336|            case 1 : dictID = ip[pos]; pos++; break;
337|            case 2 : dictID = MEM_readLE16(ip+pos); pos+=2; break;
338|            case 3 : dictID = MEM_readLE32(ip+pos); pos+=4; break;
339|        }
340|        switch(fcsID)
341|        {
342|            default: assert(0);  /* impossible */
343|            case 0 : if (singleSegment) frameContentSize = ip[pos]; break;
344|            case 1 : frameContentSize = MEM_readLE16(ip+pos)+256; break;
345|            case 2 : frameContentSize = MEM_readLE32(ip+pos); break;
346|            case 3 : frameContentSize = MEM_readLE64(ip+pos); break;
347|        }
348|        if (singleSegment) windowSize = frameContentSize;
349|
350|        zfhPtr->frameType = ZSTD_frame;
351|        zfhPtr->frameContentSize = frameContentSize;
352|        zfhPtr->windowSize = windowSize;
353|        zfhPtr->blockSizeMax = (unsigned) MIN(windowSize, ZSTD_BLOCKSIZE_MAX);
354|        zfhPtr->dictID = dictID;
355|        zfhPtr->checksumFlag = checksumFlag;
356|    }
357|    return 0;
358|}

