503|size_t ZSTD_decodeLiteralsBlock(ZSTD_DCtx* dctx,
504|                          const void* src, size_t srcSize)   /* note : srcSize < BLOCKSIZE */
505|{
506|    if (srcSize < MIN_CBLOCK_SIZE) return ERROR(corruption_detected);
507|
508|    {   const BYTE* const istart = (const BYTE*) src;
509|        symbolEncodingType_e const litEncType = (symbolEncodingType_e)(istart[0] & 3);
510|
511|        switch(litEncType)
512|        {
513|        case set_repeat:
514|            if (dctx->litEntropy==0) return ERROR(dictionary_corrupted);
515|            /* fall-through */
516|        case set_compressed:
517|            if (srcSize < 5) return ERROR(corruption_detected);   /* srcSize >= MIN_CBLOCK_SIZE == 3; here we need up to 5 for case 3 */
518|            {   size_t lhSize, litSize, litCSize;
519|                U32 singleStream=0;
520|                U32 const lhlCode = (istart[0] >> 2) & 3;
521|                U32 const lhc = MEM_readLE32(istart);
522|                switch(lhlCode)
523|                {
524|                case 0: case 1: default:   /* note : default is impossible, since lhlCode into [0..3] */
525|                    /* 2 - 2 - 10 - 10 */
526|                    singleStream = !lhlCode;
527|                    lhSize = 3;
528|                    litSize  = (lhc >> 4) & 0x3FF;
529|                    litCSize = (lhc >> 14) & 0x3FF;
530|                    break;
531|                case 2:
532|                    /* 2 - 2 - 14 - 14 */
533|                    lhSize = 4;
534|                    litSize  = (lhc >> 4) & 0x3FFF;
535|                    litCSize = lhc >> 18;
536|                    break;
537|                case 3:
538|                    /* 2 - 2 - 18 - 18 */
539|                    lhSize = 5;
540|                    litSize  = (lhc >> 4) & 0x3FFFF;
541|                    litCSize = (lhc >> 22) + (istart[4] << 10);
542|                    break;
543|                }
544|                if (litSize > ZSTD_BLOCKSIZE_MAX) return ERROR(corruption_detected);
545|                if (litCSize + lhSize > srcSize) return ERROR(corruption_detected);
546|
547|                if (HUF_isError((litEncType==set_repeat) ?
548|                                    ( singleStream ?
549|                                        HUF_decompress1X_usingDTable(dctx->litBuffer, litSize, istart+lhSize, litCSize, dctx->HUFptr) :
550|                                        HUF_decompress4X_usingDTable(dctx->litBuffer, litSize, istart+lhSize, litCSize, dctx->HUFptr) ) :
551|                                    ( singleStream ?
552|                                        HUF_decompress1X2_DCtx_wksp(dctx->entropy.hufTable, dctx->litBuffer, litSize, istart+lhSize, litCSize,
553|                                                                    dctx->entropy.workspace, sizeof(dctx->entropy.workspace)) :
554|                                        HUF_decompress4X_hufOnly_wksp(dctx->entropy.hufTable, dctx->litBuffer, litSize, istart+lhSize, litCSize,
555|                                                                      dctx->entropy.workspace, sizeof(dctx->entropy.workspace)))))
556|                    return ERROR(corruption_detected);
557|
558|                dctx->litPtr = dctx->litBuffer;
559|                dctx->litSize = litSize;
560|                dctx->litEntropy = 1;
561|                if (litEncType==set_compressed) dctx->HUFptr = dctx->entropy.hufTable;
562|                memset(dctx->litBuffer + dctx->litSize, 0, WILDCOPY_OVERLENGTH);
563|                return litCSize + lhSize;
564|            }
565|
566|        case set_basic:
567|            {   size_t litSize, lhSize;
568|                U32 const lhlCode = ((istart[0]) >> 2) & 3;
569|                switch(lhlCode)
570|                {
571|                case 0: case 2: default:   /* note : default is impossible, since lhlCode into [0..3] */
572|                    lhSize = 1;
573|                    litSize = istart[0] >> 3;
574|                    break;
575|                case 1:
576|                    lhSize = 2;
577|                    litSize = MEM_readLE16(istart) >> 4;
578|                    break;
579|                case 3:
580|                    lhSize = 3;
581|                    litSize = MEM_readLE24(istart) >> 4;
582|                    break;
583|                }
584|
585|                if (lhSize+litSize+WILDCOPY_OVERLENGTH > srcSize) {  /* risk reading beyond src buffer with wildcopy */
586|                    if (litSize+lhSize > srcSize) return ERROR(corruption_detected);
587|                    memcpy(dctx->litBuffer, istart+lhSize, litSize);
588|                    dctx->litPtr = dctx->litBuffer;
589|                    dctx->litSize = litSize;
590|                    memset(dctx->litBuffer + dctx->litSize, 0, WILDCOPY_OVERLENGTH);
591|                    return lhSize+litSize;
592|                }
593|                /* direct reference into compressed stream */
594|                dctx->litPtr = istart+lhSize;
595|                dctx->litSize = litSize;
596|                return lhSize+litSize;
597|            }
598|
599|        case set_rle:
600|            {   U32 const lhlCode = ((istart[0]) >> 2) & 3;
601|                size_t litSize, lhSize;
602|                switch(lhlCode)
603|                {
604|                case 0: case 2: default:   /* note : default is impossible, since lhlCode into [0..3] */
605|                    lhSize = 1;
606|                    litSize = istart[0] >> 3;
607|                    break;
608|                case 1:
609|                    lhSize = 2;
610|                    litSize = MEM_readLE16(istart) >> 4;
611|                    break;
612|                case 3:
613|                    lhSize = 3;
614|                    litSize = MEM_readLE24(istart) >> 4;
615|                    if (srcSize<4) return ERROR(corruption_detected);   /* srcSize >= MIN_CBLOCK_SIZE == 3; here we need lhSize+1 = 4 */
616|                    break;
617|                }
618|                if (litSize > ZSTD_BLOCKSIZE_MAX) return ERROR(corruption_detected);
619|                memset(dctx->litBuffer, istart[lhSize], litSize + WILDCOPY_OVERLENGTH);
620|                dctx->litPtr = dctx->litBuffer;
621|                dctx->litSize = litSize;
622|                return lhSize+1;
623|            }
624|        default:
625|            return ERROR(corruption_detected);   /* impossible */
626|        }
627|    }
